private val accountB = Any()

fun main(args: Array<String>) {
    val stayAlive = args.firstOrNull() == "wait"
    val t1 = Thread({ move(accountA, accountB) }, "transfer-A-to-B").apply { isDaemon = true; start() }
    val t2 = Thread({ move(accountB, accountA) }, "transfer-B-to-A").apply { isDaemon = true; start() }
    Thread.sleep(1_000)

    val mx = ManagementFactory.getThreadMXBean()
    val ids = mx.findDeadlockedThreads()           // what a health check can ask the JVM
    println("deadlocked threads: ${ids?.size ?: 0}")
    ids?.let { mx.getThreadInfo(it) }?.forEach { info ->
        println("  ${info.threadName} is ${info.threadState}, wants a lock held by ${info.lockOwnerName}")
    }
    if (stayAlive) {
        val pid = ProcessHandle.current().pid()
        println("pid $pid: run  jcmd $pid Thread.print  in another terminal (60 s)")
        Thread.sleep(60_000)
    }
}

private fun move(from: Any, to: Any) {
    synchronized(from) {
        Thread.sleep(300)                          // widen the window: the other thread takes its first lock now
        synchronized(to) {
            println("${Thread.currentThread().name} moved the money")
        }
    }
}

sections.body:
Give every account a stable, unique key, and always lock the lower key first, whichever way the money moves:

```java
void transfer(Account from, Account to, long cents) {
    Account first = from.id() < to.id() ? from : to;   // one order for everyone
    Account second = first == from ? to : from;
    synchronized (first) {
        synchronized (second) {
            from.debit(cents);
            to.credit(cents);
        }
    }
}
```

```kotlin
fun transfer(from: Account, to: Account, cents: Long) {
    val first = if (from.id < to.id) from else to      // one order for everyone
    val second = if (first === from) to else from
    synchronized(first) {
        synchronized(second) {
            from.debit(cents)
            to.credit(cents)
        }
    }
}
```

Now `transfer(a, b)` and `transfer(b, a)` both lock `a` first. Whoever gets `a` gets to run. The other waits for `a` while holding nothing, which is plain contention, not deadlock.

Three details make or break this.

The key must be unique and must never change. An account id or an IBAN works. `hashCode()` does not: two different objects can share one, and then two threads may again disagree about the order. If you have no natural key, *Java Concurrency in Practice* shows a tie-breaker: compare `System.identityHashCode`, and on a tie take one extra global lock first.

The rule must be global. Each method locking in a sensible-looking order is not enough. One method that locks account then customer, and another that locks customer then account, recreate the cycle. Put the ordering in one helper and make every caller use it.

The order must survive calls you don't see. If you call a listener, a repository or any other alien code while you hold a lock, that code may take locks of its own in a different order. That is the rule from lesson 4 of this track again: copy what you need, release the lock, then call out.

In the lab, `Account` has a `ReentrantLock` instead of using `synchronized`, so that part 2 can use `tryLock`. The ordering idea is the same.

code.src:
package workbench.concurrency.l06;

/** The same opposite transfers, with every thread taking the locks in one global order. */
public class OrderedLocks {
    record Acct(int id, long[] balance) {}

    public static void main(String[] args) throws InterruptedException {
        Acct a = new Acct(1, new long[] {1_000_000});
        Acct b = new Acct(2, new long[] {1_000_000});
        Thread t1 = new Thread(() -> { for (int i = 0; i < 100_000; i++) move(a, b, 1); }, "A-to-B");
        Thread t2 = new Thread(() -> { for (int i = 0; i < 100_000; i++) move(b, a, 1); }, "B-to-A");
        long t0 = System.nanoTime();
        t1.start();
        t2.start();
        t1.join();
        t2.join();
        System.out.printf("200,000 opposite transfers in %d ms, total still %,d%n",
                (System.nanoTime() - t0) / 1_000_000, a.balance()[0] + b.balance()[0]);
    }

    static void move(Acct from, Acct to, long cents) {
        Acct first = from.id() < to.id() ? from : to;    // lower id first, whatever the direction
        Acct second = first == from ? to : from;
        synchronized (first) {
            synchronized (second) {
                from.balance()[0] -= cents;
                to.balance()[0] += cents;
            }
        }
    }
}

