void transfer(Account from, Account to, long cents) {
    Account first = from.id() < to.id() ? from : to;
    Account second = first == from ? to : from;
    first.lock().lock();
    try {
        second.lock().lock();
        try {
            from.debit(cents);
            to.credit(cents);
        } finally {
            second.lock().unlock();
        }
    } finally {
        first.lock().unlock();
    }
}

kotlin.src:
fun transfer(from: Account, to: Account, cents: Long) {
    val first = if (from.id < to.id) from else to
    val second = if (first === from) to else from
    first.lock().withLock {                 // kotlin.concurrent.withLock: lock, try, finally unlock
        second.lock().withLock {
            from.debit(cents)
            to.credit(cents)
        }
    }
}

