class Ledger {
    synchronized void post(Entry e) {
        entries.add(e);
        auditLog.record(e);              // calls AuditLog while holding the Ledger lock
    }
    synchronized long balance() { return sum(entries); }
}

class AuditLog {
    synchronized void record(Entry e) { pending.add(e); }
    synchronized void flush() {
        long b = ledger.balance();       // calls Ledger while holding the AuditLog lock
        write(pending, b);
        pending.clear();
    }
}

