class Ledger(private val auditLog: AuditLog) {
    @Synchronized fun post(e: Entry) {
        entries += e
        auditLog.record(e)               // calls AuditLog while holding the Ledger lock
    }
    @Synchronized fun balance(): Long = sum(entries)
}

class AuditLog {
    @Synchronized fun record(e: Entry) { pending += e }
    @Synchronized fun flush() {
        val b = ledger.balance()         // calls Ledger while holding the AuditLog lock
        write(pending, b)
        pending.clear()
    }
}

