void post(Entry e) {
    synchronized (this) { entries.add(e); }
    auditLog.record(e);                  // 1. no Ledger lock held while calling out
}

void flush() {
    long b = ledger.balance();           // 2. read the balance before taking our own lock
    List<Entry> batch;
    synchronized (this) { batch = List.copyOf(pending); pending.clear(); }
    write(batch, b);                     // 3. slow I/O with no lock at all
}

